document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("lineVideo"),t=document.getElementById("videoTitle"),n=document.getElementById("toggleVideoBtn"),i=[{title:"Production Line",src:"../video/生產線.mp4"},{title:"Non-Metal Production Line",src:"../video/非金屬生產線.mp4"}];let d=0;n.addEventListener("click",()=>{d=(d+1)%i.length,e.src=i[d].src,t.innerText=`Currently Playing: ${i[d].title}`,e.play();const o=i[(d+1)%i.length].title;n.title=`Switch to ${o}`})});